package com.justjava.humanresource.employeeexit.service;
import com.justjava.humanresource.core.enums.*; import com.justjava.humanresource.employeeexit.entity.EmployeeExitCase; import com.justjava.humanresource.employeeexit.enums.*; import com.justjava.humanresource.employeeexit.repository.EmployeeExitCaseRepository; import com.justjava.humanresource.hr.entity.Employee; import com.justjava.humanresource.hr.repository.*; import com.justjava.humanresource.orgStructure.enums.ReportingType; import com.justjava.humanresource.orgStructure.repositories.EmployeeReportingLineRepository; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.*;
@Service @RequiredArgsConstructor public class EmployeeExitFinalizationService {
 private final EmployeeExitService exitService; private final EmployeeExitReadinessService readiness; private final EmployeeExitCaseRepository exits; private final EmployeeRepository employees; private final EmployeePositionHistoryRepository positions; private final EmployeeReportingLineRepository reportingLines; private final EmployeeExitActivityService activity;
 @Transactional public void finalizeEmployment(Long exitId){EmployeeExitCase x=exitService.require(exitId);if(x.getStatus()==ExitStatus.COMPLETED)return;if(x.getStatus()!=ExitStatus.READY_TO_EXIT)throw new IllegalStateException("Exit is not ready for finalization.");var result=readiness.validate(exitId);if(result.blockers().stream().anyMatch(b->b.category()!=com.justjava.humanresource.employeeexit.dto.ExitReadinessBlocker.Category.ACCESS_REVOCATION_PENDING))throw new IllegalStateException("Exit readiness blockers remain: "+result.summary());if(x.getEffectiveExitDate()==null||x.getEffectiveExitDate().isAfter(LocalDate.now()))throw new IllegalStateException("Exit effective date has not arrived.");Employee e=employees.findById(x.getEmployeeId()).orElseThrow();e.setEmploymentStatus(targetStatus(x.getExitType()));e.setPayrollEnabled(false);e.setKpiEnabled(false);e.setStatus(RecordStatus.INACTIVE);employees.save(e);positions.findByEmployee_IdAndCurrentTrue(e.getId()).ifPresent(p->{p.setCurrent(false);p.setEffectiveTo(x.getEffectiveExitDate());p.setStatus(RecordStatus.INACTIVE);positions.save(p);});reportingLines.findActiveLine(e.getId(),ReportingType.PRIMARY).ifPresent(r->{r.setEffectiveTo(x.getEffectiveExitDate());r.setStatus(RecordStatus.INACTIVE);reportingLines.save(r);});activity.record(exitId,"EMPLOYMENT_FINALIZED","Employee employment and active position were closed",null,null);}
 @Transactional public void completeCase(Long exitId){EmployeeExitCase x=exitService.require(exitId);if(x.getStatus()==ExitStatus.COMPLETED)return;x.setStatus(ExitStatus.COMPLETED);x.setCompletedAt(LocalDateTime.now());exits.save(x);activity.record(exitId,"COMPLETED","Employee exit completed",null,null);}
 private EmploymentStatus targetStatus(ExitType t){return switch(t){case RESIGNATION,ABANDONMENT->EmploymentStatus.RESIGNED;case RETIREMENT->EmploymentStatus.RETIRED;default->EmploymentStatus.TERMINATED;};}
}
